/** 绿茵视界公共及社区模块；本人负责，AI辅助编写。 */ use yii\helpers\Html;$this->title='我的话题'; ?><h1>我的话题</h1><p><?= Html::a('发起新讨论',['create'],['class'=>'button']) ?></p><table><tr><th>标题</th><th>状态</th><th>操作</th></tr><?php foreach($provider->models as $p): ?><tr><td><?= Html::encode($p->title) ?></td><td><?= Html::encode(['pending'=>'待审核','published'=>'已公开','rejected'=>'已驳回','archived'=>'已撤下'][$p->status]) ?></td><td><div class="actions"><?php if($p->status!=='archived'): ?><?= Html::a('编辑',['edit','id'=>$p->id]) ?><?= Html::beginForm(['withdraw','id'=>$p->id],'post') ?><button>撤下</button><?= Html::endForm() ?><?php endif ?></div></td></tr><?php endforeach ?></table><?= \yii\widgets\LinkPager::widget(['pagination'=>$provider->pagination]) ?>
